import{_ as r,o as a,c as i,aw as t}from"./chunks/framework.DLufY-ao.js";const l="/workbook/assets/fiber-phases.1eHqVhLe.png",b=JSON.parse('{"title":"React Fiber Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/framework-react/react/fiber/common.md","filePath":"wiki/dev-commit/framework-react/react/fiber/common.md"}'),o={name:"wiki/dev-commit/framework-react/react/fiber/common.md"};function c(n,e,s,u,h,d){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="react-fiber-architecture" tabindex="-1">React Fiber Architecture <a class="header-anchor" href="#react-fiber-architecture" aria-label="Permalink to &quot;React Fiber Architecture&quot;">​</a></h1><h2 id="информация" tabindex="-1">Информация <a class="header-anchor" href="#информация" aria-label="Permalink to &quot;Информация&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">INFO</p><ul><li><a href="https://www.youtube.com/watch?v=4p9ISqIx1zI" target="_blank" rel="noreferrer">https://www.youtube.com/watch?v=4p9ISqIx1zI</a> - YouTube. Лин Кларк. Как Fiber сделал React значительно быстрее</li></ul></div><div class="tip custom-block"><p class="custom-block-title">Определения</p><ul><li><strong>React Fiber</strong> - переделанная реализация алгоритма reconciliation</li><li>Fiber - легоковесная реализация потоков</li><li>Цель Fiber - позволить React воспользоваться планированием</li><li><strong>Планирование</strong> - это процесс, который определяет когда работа должна быть выполнена</li><li><strong>Работа</strong> - любые вычисления, которые должны быть выполнены. Работа – это обычно результат апдейта (например вызов setState)</li></ul></div><ul><li><em>Цель</em> в увеличении производительности при разработке таких задач как анимация, организация элементов на странице и движение элементов</li><li><em>Главная особенность</em> - инкрементный рендеринг: способность разделять работу рендера на единицы и распределять их между множественными фреймами.</li></ul><h2 id="алгоритм" tabindex="-1">Алгоритм <a class="header-anchor" href="#алгоритм" aria-label="Permalink to &quot;Алгоритм&quot;">​</a></h2><ol><li>Есть очередь того, что нужно перерисовать</li><li>У каждого элемента очереди есть приоритеты</li><li>Механизм реконсилинга выбирает из очереди наиболее приоритетные задачи, их выполняет пока не прошло 16ms и не пришло время отдавать управление браузеру</li></ol><h2 id="фазы" tabindex="-1">Фазы <a class="header-anchor" href="#фазы" aria-label="Permalink to &quot;Фазы&quot;">​</a></h2><ul><li>Фазу 1 можно прервать</li><li>Фазу 2 нельзя прервать</li></ul><img src="'+l+'" width="700px"><h2 id="сравнение-с-предыдущим-алгоритмом" tabindex="-1">Сравнение с предыдущим алгоритмом <a class="header-anchor" href="#сравнение-с-предыдущим-алгоритмом" aria-label="Permalink to &quot;Сравнение с предыдущим алгоритмом&quot;">​</a></h2><ul><li>Предудущий алгоритм обходит всё дерево компонент рекурсивно и вызывает все render-функции в рамках одного тика Event Loop.</li></ul><h2 id="error-boundarys" tabindex="-1">Error Boundarys <a class="header-anchor" href="#error-boundarys" aria-label="Permalink to &quot;Error Boundarys&quot;">​</a></h2><ul><li>Каждая отрисовка является легковесным Файбером стало возможно реализовать границы ошибок (Error Boundarys)</li><li>Теперь падения в одном компоненте не приводит к падению перерисовок во всех других компонентов</li><li>Будет разрушено дерево компонента, который упал. Но за пределы разрушенного дерева, ошибка не выйдет</li></ul><h2 id="из-компонентов-react-можно-возвращать" tabindex="-1">Из компонентов React можно возвращать: <a class="header-anchor" href="#из-компонентов-react-можно-возвращать" aria-label="Permalink to &quot;Из компонентов React можно возвращать:&quot;">​</a></h2><ul><li>DOM-узел</li><li>Число</li><li>Строку</li><li>Массив (DOM-узелов / чисел / строк)</li></ul><blockquote><p>Нет соответствия: 1 виртуальный узел - 1 узел в HTML</p></blockquote><h2 id="повторныи-рендеринг-re-renderen" tabindex="-1">Повторный рендеринг (Re-renderen) <a class="header-anchor" href="#повторныи-рендеринг-re-renderen" aria-label="Permalink to &quot;Повторный рендеринг (Re-renderen)&quot;">​</a></h2><ol><li>Сверка (Reconciler)</li><li>Перерисовка (Rerender): ReactDOM, React Native</li></ol>',19)])])}const f=r(o,[["render",c]]);export{b as __pageData,f as default};
